import os
import shutil


def task_func(src_folder, backup_dir):
    if not os.path.isdir(src_folder):
        raise ValueError("Source folder does not exist")

    src_norm = os.path.normpath(src_folder)
    src_name = os.path.basename(src_norm) or os.path.basename(os.path.abspath(src_norm)) or "source_backup"
    backup_path = os.path.join(backup_dir, src_name)

    try:
        os.makedirs(backup_dir, exist_ok=True)

        if os.path.exists(backup_path):
            if os.path.isdir(backup_path) and not os.path.islink(backup_path):
                shutil.rmtree(backup_path)
            else:
                os.remove(backup_path)

        shutil.copytree(src_folder, backup_path)
    except Exception:
        return False

    try:
        shutil.rmtree(src_folder)
    except Exception as exc:
        raise Exception("Error occurred while deleting the source folder") from exc

    return True
